/** A skippable FieldShift opening sequence, with replay control in Settings. */
const copy={en:{eyebrow:'FIELD SHIFT / EARTH + LAND',title:'Every field begins<br>with a signal.',body:'See the land. Read the season. Shape the next move.',enter:'Enter workspace',skip:'Skip intro',replay:'Replay introduction',replayBody:'Watch the FieldShift opening sequence again.'},fr:{eyebrow:'FIELD SHIFT / TERRE + CULTURE',title:'Chaque champ commence<br>par un signal.',body:'Voyez la terre. Lisez la saison. Préparez la prochaine étape.',enter:'Entrer dans l’espace',skip:'Passer l’intro',replay:'Revoir l’introduction',replayBody:'Revoir la séquence d’ouverture de FieldShift.'},ar:{eyebrow:'فيلد شيفت / الأرض + الزراعة',title:'كل حقل يبدأ<br>بإشارة.',body:'شاهد الأرض. اقرأ الموسم. ارسم خطوتك التالية.',enter:'دخول مساحة العمل',skip:'تخطي المقدمة',replay:'إعادة المقدمة',replayBody:'شاهد تسلسل افتتاح فيلد شيفت مرة أخرى.'}};
const key='fieldshift.intro.seen';
export function initIntro({language='en'}={}){
  let current=copy[language]?language:'en';
  const overlay=document.createElement('section');overlay.className='fieldshift-intro';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','FieldShift introduction');
  overlay.innerHTML='<div class="intro-stars" aria-hidden="true"></div><div class="intro-orbit orbit-one" aria-hidden="true"></div><div class="intro-orbit orbit-two" aria-hidden="true"></div><div class="intro-field-lines" aria-hidden="true"></div><button class="intro-skip" type="button"></button><div class="intro-core"><div class="intro-mark" aria-hidden="true"><img src="assets/logo.svg" alt=""><span></span></div><span class="intro-eyebrow"></span><h1></h1><p></p><button class="intro-enter" type="button"></button><span class="intro-progress" aria-hidden="true"><i></i></span></div>';
  document.body.append(overlay);
  const apply=()=>{const words=copy[current];overlay.querySelector('.intro-eyebrow').textContent=words.eyebrow;overlay.querySelector('h1').innerHTML=words.title;overlay.querySelector('p').textContent=words.body;overlay.querySelector('.intro-enter').textContent=words.enter;overlay.querySelector('.intro-skip').textContent=words.skip;overlay.querySelector('.intro-skip').setAttribute('aria-label',words.skip);};
  const close=()=>{overlay.classList.add('leaving');sessionStorage.setItem(key,'1');setTimeout(()=>overlay.hidden=true,420);document.body.classList.remove('intro-open');document.querySelector('.topbar-field')?.focus();};
  const open=()=>{overlay.hidden=false;overlay.classList.remove('leaving');void overlay.offsetWidth;overlay.classList.add('running');document.body.classList.add('intro-open');overlay.querySelector('.intro-skip').focus();};
  overlay.querySelector('.intro-enter').onclick=close;overlay.querySelector('.intro-skip').onclick=close;overlay.addEventListener('keydown',event=>{if(event.key==='Escape')close();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!overlay.hidden)close();});
  const panel=document.querySelector('.settings-panel');const row=document.createElement('div');row.className='setting-item intro-replay-setting';row.innerHTML='<div><b></b><p></p></div><button type="button" class="button secondary small"></button>';panel.append(row);
  const updateRow=()=>{const words=copy[current];row.querySelector('b').textContent=words.replay;row.querySelector('p').textContent=words.replayBody;row.querySelector('button').textContent=words.replay;};row.querySelector('button').onclick=open;
  window.addEventListener('fieldshift:language',event=>{current=copy[event.detail]?event.detail:'en';apply();updateRow();});apply();updateRow();if(!sessionStorage.getItem(key))requestAnimationFrame(open);else overlay.hidden=true;return{open};
}
